use crate::BacktestSignal;
#[derive(Debug,Clone,Copy,PartialEq)] pub struct PerformanceMetrics{pub profit_factor:f64,pub max_drawdown_pct:f64,pub expectancy_pct:f64,pub payoff_ratio:f64}
pub fn performance_metrics(signals:&[BacktestSignal])->PerformanceMetrics{if signals.is_empty(){return PerformanceMetrics{profit_factor:0.0,max_drawdown_pct:0.0,expectancy_pct:0.0,payoff_ratio:0.0}}let gains:Vec<f64>=signals.iter().filter(|s|s.return_pct>0.0).map(|s|s.return_pct).collect();let losses:Vec<f64>=signals.iter().filter(|s|s.return_pct<0.0).map(|s|s.return_pct.abs()).collect();let gross_profit=gains.iter().sum::<f64>();let gross_loss=losses.iter().sum::<f64>();let profit_factor=if gross_loss>0.0{gross_profit/gross_loss}else if gross_profit>0.0{f64::INFINITY}else{0.0};let avg_win=if gains.is_empty(){0.0}else{gross_profit/gains.len() as f64};let avg_loss=if losses.is_empty(){0.0}else{gross_loss/losses.len() as f64};let payoff_ratio=if avg_loss>0.0{avg_win/avg_loss}else{0.0};let expectancy_pct=signals.iter().map(|s|s.return_pct).sum::<f64>()/signals.len() as f64;let mut equity=1.0;let mut peak=1.0;let mut max_dd=0.0;for s in signals{equity*=1.0+s.return_pct/100.0;peak=peak.max(equity);if peak>0.0{let dd=(peak-equity)/peak*100.0;if dd>max_dd{max_dd=dd;}}}PerformanceMetrics{profit_factor,max_drawdown_pct:max_dd,expectancy_pct,payoff_ratio}}
#[cfg(test)]mod tests{use super::*;use crate::BacktestSignal;fn s(r:f64)->BacktestSignal{BacktestSignal{symbol:"X".into(),timestamp:0,score:80.0,entry_price:100.0,exit_price:100.0*(1.0+r/100.0),return_pct:r,win:r>0.0}}#[test]fn metrics_measure_drawdown(){let m=performance_metrics(&[s(10.0),s(-20.0),s(5.0)]);assert!(m.max_drawdown_pct>19.0);assert!(m.expectancy_pct<0.0);}}
